import{_ as t,l as n,o as e,c as s,v as o,p as l,x as i,d as p,i as A,S as c}from"./chunks/framework.InCnrqk-.js";const N=JSON.parse('{"title":"Cook–Levin 定理","description":"","frontmatter":{"title":"Cook–Levin 定理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cook-levin.md","filePath":"cs/cook-levin.md","lastUpdated":1789023840000}'),T={name:"cs/cook-levin.md"};function d(h,a,S,_,P,m){const r=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="cook–levin-定理" tabindex="-1">Cook–Levin 定理 <a class="header-anchor" href="#cook–levin-定理" aria-label="Permalink to &quot;Cook–Levin 定理&quot;">​</a></h1><div class="epigraph"><p>SAT 是 NP 完全的：任意多项式时间验证器的计算表格，都可以多项式变成一份布尔公式，可满足当且仅当证书被接受。</p><footer>—— 据 Cook, 1971；Levin, 1973；Sipser 整理</footer></div><p><a href="/cs/nl-l-classes">上一课</a>把对数空间类钉完。主干<a href="/cs/p-vs-np">P 与 NP</a> 定义了类，<a href="/cs/np-reduction">多项式归约</a> 练了箭头，完全性那一课点名 SAT。本课是补层：把 <strong>Cook–Levin</strong> 的构造形状写清——表格、局部窗口、为何落在 NP。不重定义证书，不列 Karp 的 21 题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NP 机 \\(N\\) 在 \\(x\\) 上有多项式长接受路 \\(\\iff\\) 存在证书。把运行摊成时间 \\(\\times\\) 空间的表格：每格是带符号或状态。合法表格 = 起始行写 \\(x\\)、每 \\(2\\times 3\\) 窗口符合 \\(\\delta\\)、某格出现接受。窗口条件是常数大小布尔约束。合取全体窗口得公式 \\(\\varphi_x\\)，变量即格内容。\\(x\\in L(N)\\iff\\varphi_x\\in\\mathrm{SAT}\\)。\\(|\\varphi_x|\\) 多项式。故一切 NP 问题 \\(\\le_p\\) SAT。SAT 本身在 NP：猜赋值，验子句。于是 SAT NP 完全。</p><p>3SAT 再局部改写成三元子句，完全性留下。</p><h3 id="不是「sat-很难」的经验" tabindex="-1">不是「SAT 很难」的经验 <a class="header-anchor" href="#不是「sat-很难」的经验" aria-label="Permalink to &quot;不是「SAT 很难」的经验&quot;">​</a></h3><p>定理是完全性，不是下界。若 SAT 在 P 则 \\(P=NP\\)。表格构造对确定机同样能做，那只会证明 CIRCUIT-SAT 一类 P 完全（空间对数归约），对象换了。</p><p><span class="marginnote">Cook 1971（Turing 归约味道更重）；Levin 1973 独立，且强调搜索问题。Garey–Johnson、Sipser 用 Karp 多一版表格。本课用多一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 \\(T\\times S\\) 表，\\(T,S\\) 多项式。列窗口合法性。输出 CNF（或任意公式，再多项式化 CNF）。强调变量个数 \\(O(T S\\log|\\Gamma|)\\)。不要把归结或 DPLL 请进来——那是求解，后课逻辑单元。</p>',11)),(e(),l(c,null,{default:i(()=>[A(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NTM%5B%22NP%20%E6%9C%BA%E8%BF%90%E8%A1%8C%22%5D%20--%3E%20TAB%5B%22%E6%97%B6%E9%97%B4-%E7%A9%BA%E9%97%B4%E8%A1%A8%22%5D%0A%20%20TAB%20--%3E%20WIN%5B%22%E5%B1%80%E9%83%A8%E7%AA%97%E5%8F%A3%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20WIN%20--%3E%20SAT%5B%22%E7%AD%89%E4%BB%B7%20SAT%20%E5%85%AC%E5%BC%8F%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p><a href="/cs/boolean-algebra">布尔代数</a> 已给与或非；这里公式是符号串，真值是证书。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>局部性是关键：TM 一步只动一头，故全局合法 = 处处窗口合法。换 RAM 或电路，同样「局部检查计算」。后课电路复杂性把这张表竖过来变成电路族。PCP 会再把验证局部到查几个比特。</p><p>有了 SAT 完全，Karp 清单才是「从 SAT 往外化」，不必再对每个问题摊表格。</p><p>窗口宽 \\(O(1)\\) 是因为 TM 头一步只碰常数格。换成 RAM 要先模拟成 TM，或直接用电路。3SAT 的拆句在主干<a href="/cs/sat-3sat">SAT</a> 已写：长子句引进新变元。本课表格是根，Karp 清单是从根长出的枝，不必再对团问题摊一遍运行表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 3SAT 的子句改写细节全文，不引入 1-in-3 SAT。不讨论平均情形 SAT。后课默认：NP 完全的根是 Cook–Levin 表格。下一课 coNP 与多项式层级。</p><p>表格构造一旦会写，SAT 就是 NP 的根，不必对每个新问题再摊运行记录。后课 coNP 问的是否实例有没有同样短的证，不是再证一遍 SAT 完全。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SAT NP 完全：计算表的局部约束 \\(\\to\\) 公式。</li><li>完全性是归约，不是指数下界。</li><li>此后 NPC 证明从 SAT 出发即可。</li><li>出处：Cook, 1971；Levin, 1973。</li></ul>',10))])}const k=t(T,[["render",d]]);export{N as __pageData,k as default};
